/**
 * P-14.3.4.4
 * Nomenclature of Organic Chemistry: IUPAC Recommendations and Preferred Names 2013 (the Blue Book)
 *
 * “Locants are omitted when no isomer can be generated by moving suffixes and/or prefixes (if any)
 * from their position to another or by interchanging them between two different positions.
 * As an exception the locant is not omitted from propa-1,2-diene, propan-2-one, butan-2-one,
 * prop-2-enoic acid and prop-2-ynoic acid although unambiguous without a locant.”
 *
 * The whole section is in the Blue Book.
 *
 * Corrections from the IUPAC list of Blue Book errors, already in the Blue Book's web text:
 *   Page 32, P-14.3.4.4, example 4. [corrected 5 July 2018]
 *     For (not 1-ethylidene-2-methylidenetriphosphoxane)
 *     read (not 1-ethylidene-5-methylidenetriphosphoxane)
 *   Page 32, P-14.3.4.4, after examples add. [corrected 9 April 2025]
 *     For As an exception the locant is not omitted from propan-2-one, butan-2-one, prop-2-enoic acid
 *     and prop-2-ynoic acid although unambiguous without a locant.
 *     read As an exception the locant is not omitted from propa-1,2-diene, propan-2-one, butan-2-one,
 *     prop-2-enoic acid and prop-2-ynoic acid although unambiguous without a locant.
 *
 * Examples with a drawing are drawn, not written out, in the Blue Book. The checks read
 * their names, but can only check the structure against the drawing once the drawings are used.
 */
import { checkRule } from '../support/checkRule.js';

checkRule('P-14.3.4.4', [
  { formula: 'CH3-CH=N-NH–', preferredPrefix: 'ethylidenehydrazinyl', notNames: ['2-ethylidenehydrazin-1-yl'] },
  { formula: 'HC≡Si-Si≡C-CH3', name: 'ethylidyne(methylidyne)disilane', notNames: ['1-ethylidyne-2-methylidynedisilane'] },
  { formula: 'C6H5-CH=SiH-Si(=CH-C6H5)–', preferredPrefix: 'dibenzylidenedisilanyl', notNames: ['1,2-dibenzylidenedisilan-1-yl'] },
  { formula: 'H2C=P-O-PH-O-P=CH-CH3', pin: 'ethylidene(methylidene)triphosphoxane', notNames: ['1-ethylidene-5-methylidenetriphosphoxane'] },
  { formula: 'H2Si=N-NH-Cl', preselectedName: 'chloro(silylidene)hydrazine', notNames: ['1-chloro-2-silylidenehydrazine'] },
  { formula: 'Br-S-S-CH3', notNames: ['bromo(methyl)disulfane see P-63.3.1', '1-bromo-2-methyldisulfane'] },
  { formula: 'O=C=CH–', preferredPrefix: 'oxoethenyl' },
  { formula: 'Cl-N=N–', preferredPrefix: 'chlorodiazenyl' },
  // Drawn in the Blue Book.
  { drawing: 'P1gif/P1403h2.gif', pin: '1H-tetrazole', notNames: ['1H-1,2,3,4-tetrazole'] },
  { formula: 'CH3-CH2-CH=SiH-Si(=CH-CH3)–', preferredPrefix: '1-ethylidene-2-propylidenedisilan-1-yl' },
  { formula: 'CH3-CH=SiH-SiH2-Cl', pin: '1-chloro-2-ethylidenedisilane' },
  { formula: 'Cl-CH=CH–', preferredPrefix: '2-chloroethen-1-yl' },
]);
